css:
.dcx *{ box-sizing: border-box; }
.dcx{ margin: 0; background: #F5F7F3; }
.dcx a[style*="inline-flex"]{ white-space: nowrap; }
.dcx img{ max-width: 100%; height: auto; }
@media (prefers-reduced-motion: reduce){.dcx *,.dcx *::before,.dcx *::after{ animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; }
}
.dcx a{ color: #0B6B3F; text-decoration: none; }
.dcx a:hover{ color: #16A85F; }
.dcx :focus-visible{ outline: 2px solid #16A85F; outline-offset: 3px; }
.dcx [data-mega]{ display: none; }
.dcx [data-navitem]:hover [data-mega],.dcx [data-mega]:hover{ display: block; }
.dcx [data-burger]{ display: none; }
@media (max-width: 1180px){.dcx [data-navlinks],.dcx [data-navlogin]{ display: none !important; }
.dcx [data-burger]{ display: inline-flex !important; }
.dcx [data-hero]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-mock]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-mock-side]{ border-right: 0 !important; border-bottom: 1px solid rgba(16,32,26,.08) !important; }
.dcx [data-mock-side] > ul{ flex-direction: row !important; flex-wrap: wrap !important; }
.dcx [data-mock-side] > ul > li{ flex: 0 0 auto !important; }
.dcx [data-r3]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-r4]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-teams]{ grid-template-columns: repeat(2, minmax(0,1fr)) !important; }
.dcx [data-cta]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-chan]{ grid-template-columns: repeat(5, minmax(0,1fr)) !important; }
}
@media (max-width: 720px){.dcx [data-pad]{ padding-left: 18px !important; padding-right: 18px !important; }
.dcx [data-chan]{ grid-template-columns: repeat(3, minmax(0,1fr)) !important; }
.dcx [data-r3],.dcx [data-r4],.dcx [data-teams],.dcx [data-feat]{ grid-template-columns: minmax(0,1fr) !important; }
.dcx [data-h1]{ font-size: 32px !important; }
.dcx [data-h2]{ font-size: 25px !important; }
}
